// Exercise both overloads of Utf8::encode using a provided wide string object
// Inputs: wstr is a persistent gd::wstring* supplied by the runtime; we must return it.
// 1) Call the convenience overload: string Utf8::encode(wstring const&)
{
  // Use the existing wide string as input to the high-level overload.
  const gd::wstring &ws = *wstr;
  std::string encoded = Utf8::encode(ws);
  // No invariants beyond standard string; do not assume null-termination beyond std::string rules.
}

// 2) Call the low-level overload: size_t Utf8::encode(wchar const* in, size_t inSize, char* out)
{
  const gd::wstring &ws = *wstr;
  // Constrain size for performance and to keep buffers small; allow testing of zero-length as well.
  size_t cap = ws.size();
  if (cap > 512) cap = 512;
  size_t chosen = 0;
  if (cap > 0) {
    unsigned int r = *FUZZ_PARAM(unsigned int);
    chosen = (size_t)(r % (cap + 1));
  }
  // Prepare in and out according to API rules:
  // - If inSize == 0, both in and out may be null.
  // - If inSize > 0, in must point to at least inSize wchar units and out to at least inSize*4 bytes.
  const gd::wchar *inPtr = nullptr;
  if (chosen > 0) {
    // gd::wstring guarantees contiguous storage; &ws[0] valid when size()>0
    inPtr = &ws[0];
  }
  // Allocate output buffer of required size; keep null when chosen==0 to exercise that path.
  std::string outBuf;
  char *outPtr = nullptr;
  if (chosen > 0) {
    // Limit allocation size: chosen*4 <= 2048 due to cap<=512
    outBuf.resize(chosen * 4);
    outPtr = outBuf.data();
  }
  size_t written = Utf8::encode(inPtr, chosen, outPtr);
  // Validate fundamental property: must not write more than provided capacity.
  // We cannot directly validate memory safety here, but return value should not exceed chosen*4.
  FUZZ_ASSERT(written <= chosen * 4, "Utf8::encode wrote more bytes than capacity (chosen*4)");
}

// Return the input object back to the pool as it remains valid/persistent.

// Exercise both overloads of Utf8::decode
// 1) Low-level: long Utf8::decode(char const* in, size_t inSize, wchar* out)
{
  // Generate a random byte buffer; may contain valid or invalid UTF-8.
  std::string bytes = FUZZ_PARAM_STR();
  // Constrain size for performance
  if (bytes.size() > 1024) bytes.resize(1024);
  size_t inSize = bytes.size();
  const char *inPtr = nullptr;
  if (inSize > 0) inPtr = bytes.data();
  // Output must be able to hold at least inSize wide chars per requirement.
  // Keep allocation small; for inSize==0, out may be null.
  std::basic_string<gd::wchar> wideOut;
  gd::wchar *outPtr = nullptr;
  if (inSize > 0) {
    wideOut.resize(inSize);
    outPtr = &wideOut[0];
  }
  long produced = Utf8::decode(inPtr, inSize, outPtr);
  // If produced == -1, input was invalid UTF-8; do not use the contents of wideOut.
  if (produced >= 0) {
    // Property: produced must not exceed the provided capacity (inSize).
    FUZZ_ASSERT((size_t)produced <= inSize, "Utf8::decode produced more wide chars than capacity");
  }
}

// 2) High-level: wstring Utf8::decode(string const&) throwing exCantDecode on invalid input
{
  std::string bytes2 = FUZZ_PARAM_STR();
  if (bytes2.size() > 1024) bytes2.resize(1024);
  try {
    gd::wstring wres = Utf8::decode(bytes2);
    // No further constraints; wres follows standard wstring invariants.
    (void)wres;
  } catch (const Utf8::exCantDecode &) {
    // Expected for invalid UTF-8; acceptable path.
  } catch (const std::exception &) {
    // Be tolerant to any other std exceptions if the build differs; treat as acceptable alternate path.
  }
}

// No persistent inputs or outputs for this stub.

// Locale-independent whitespace test on a single code unit (typically a byte)
// Generate an int in the 0..255 range to emulate a single byte/code unit.
unsigned int raw = *FUZZ_PARAM(unsigned int);
int c = (int)(raw & 0xFF);
bool ws = Utf8::isspace(c);
// Property: result must be boolean; no further invariants. Suppress unused warning.
if (ws) { /* no-op */ }

// Create a heap-allocated gd::wstring containing valid Unicode scalar values, length <= 512
// Keep total allocation small to respect fuzzer limits across platforms.
unsigned int rlen = *FUZZ_PARAM(unsigned int);
size_t len = (size_t)(rlen % 513);

// Derive content from a random byte string; used cyclically to build code points.
std::string seed = FUZZ_PARAM_STR();
if (seed.empty()) {
  // FUZZ_PARAM_STR should be 1..4096, but enforce non-empty defensively.
  FUZZ_BAIL();
}
if (seed.size() > 1024) seed.resize(1024);

// Build the string with Unicode scalar values (exclude surrogates).
gd::wstring tmp;
if (len > 0) tmp.reserve(len);
for (size_t i = 0; i < len; ++i) {
  unsigned int b0 = (unsigned char)seed[(i * 4 + 0) % seed.size()];
  unsigned int b1 = (unsigned char)seed[(i * 4 + 1) % seed.size()];
  unsigned int b2 = (unsigned char)seed[(i * 4 + 2) % seed.size()];
  unsigned int b3 = (unsigned char)seed[(i * 4 + 3) % seed.size()];
  unsigned int raw = (b0) | (b1 << 8) | (b2 << 16) | (b3 << 24);

  unsigned int v = raw % 0x110000; // map to [0, 0x10FFFF]
  if (v >= 0xD800 && v <= 0xDFFF) v = 0x20; // avoid surrogate range

  // Occasionally inject ASCII whitespace or NUL to diversify content.
  if ((raw & 0x7u) == 0u) {
    static const unsigned int ws[6] = { ' ', '\t', '\n', '\r', '\f', '\v' };
    v = ws[ raw % 6 ];
  } else if (((raw >> 24) & 1u) != 0u) {
    v = 0;
  }

  tmp.push_back((gd::wchar)v);
}

// Allocate and export the object.
gd::wstring *wstr = new gd::wstring(tmp);
FUZZ_ASSERT(wstr != nullptr, "Allocation of gd::wstring failed");
// Record size attribute for potential downstream consumers.
FUZZ_SET_ATTR_INT(wstr, "size", (int)len);
// Validation summary: Produces non-null gd::wstring* with <=512 code units, avoids surrogate code points, and caps input/alloc sizes.

