import random
import struct
from typing import List, Tuple

# This generator focuses on producing valid UTF-8 byte sequences (with a sprinkling of edge cases)
# to exercise Utf8::decode in both its low-level and high-level forms.
# It creates varied content: ASCII, BMP, multi-byte, mixed scripts, boundaries, long runs, and
# optionally inserts or not a training null. Data remains valid UTF-8 by construction unless we
# purposefully add known-invalid segments in a controlled fraction to test exception paths.
# Size is capped to <= 4096 bytes (we also keep it reasonably small typically <= 1024 for parity
# with the stub, but may exceed to give additional variation; the stub truncates when needed).

# Helper: encode a single Unicode scalar to UTF-8 bytes (manual to keep control and avoid Python
# adding surrogates). Assumes 0 <= cp <= 0x10FFFF and cp not a surrogate.
def _enc_cp(cp: int) -> bytes:
    if cp <= 0x7F:
        return bytes([cp])
    if cp <= 0x7FF:
        return bytes([
            0xC0 | (cp >> 6),
            0x80 | (cp & 0x3F)
        ])
    if cp <= 0xFFFF:
        return bytes([
            0xE0 | (cp >> 12),
            0x80 | ((cp >> 6) & 0x3F),
            0x80 | (cp & 0x3F)
        ])
    return bytes([
        0xF0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3F),
        0x80 | ((cp >> 6) & 0x3F),
        0x80 | (cp & 0x3F)
    ])

# Generate a random Unicode scalar avoiding surrogate code points.
def _rand_scalar(rng: random.Random) -> int:
    while True:
        cp = rng.randrange(0x110000)
        if 0xD800 <= cp <= 0xDFFF:
            continue
        return cp

# Predefined interesting code points
_ASCII_WHITESPACE = [0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x20]
_ASCII_PUNCT = list(map(ord, list("!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~")))
_ASCII_ALNUM = list(range(ord('0'), ord('9')+1)) + list(range(ord('A'), ord('Z')+1)) + list(range(ord('a'), ord('z')+1))
_BOUNDARY_CPS = [
    0x007F,  # 1-byte max
    0x0080,  # 2-byte min
    0x07FF,  # 2-byte max
    0x0800,  # 3-byte min
    0xFFFF,  # 3-byte max
    0x10000, # 4-byte min
    0x10FFFF # 4-byte max
]
_SCRIPTS = [
    # Latin extended
    list(range(0x00C0, 0x00FF+1)),
    # Greek
    list(range(0x0370, 0x03FF+1)),
    # Cyrillic
    list(range(0x0400, 0x04FF+1)),
    # Hebrew
    list(range(0x0590, 0x05FF+1)),
    # Arabic
    list(range(0x0600, 0x06FF+1)),
    # Devanagari
    list(range(0x0900, 0x097F+1)),
    # CJK Unified Ideographs (subset window)
    list(range(0x4E00, 0x4F80)),
    # Emoji (common range)
    list(range(0x1F300, 0x1F6FF+1)),
]

# Construct a valid UTF-8 sequence from a list of code points
def _encode_cps(cps: List[int]) -> bytes:
    out = bytearray()
    for cp in cps:
        # skip surrogates if any slipped in
        if 0xD800 <= cp <= 0xDFFF:
            continue
        if not (0 <= cp <= 0x10FFFF):
            continue
        out.extend(_enc_cp(cp))
    return bytes(out)

# Builders for varied interesting payloads

def _build_ascii_block(rng: random.Random, length: int) -> bytes:
    pool = _ASCII_ALNUM + _ASCII_PUNCT + _ASCII_WHITESPACE
    cps = [rng.choice(pool) for _ in range(length)]
    return _encode_cps(cps)

def _build_boundary_sequence(rng: random.Random, count: int) -> bytes:
    cps = []
    for _ in range(count):
        cps.append(rng.choice(_BOUNDARY_CPS))
    return _encode_cps(cps)

def _build_mixed_scripts(rng: random.Random, chars: int) -> bytes:
    cps = []
    for _ in range(chars):
        script = rng.choice(_SCRIPTS)
        cp = rng.choice(script)
        # Avoid combining surrogate window (not present in these ranges, but keep guard)
        if 0xD800 <= cp <= 0xDFFF:
            cp = 0xFFFD
        cps.append(cp)
    return _encode_cps(cps)

def _build_long_run(rng: random.Random, cp: int, repeat: int) -> bytes:
    return _encode_cps([cp] * repeat)

def _build_random_valid(rng: random.Random, chars: int) -> bytes:
    cps = []
    for _ in range(chars):
        # Bias to cover different byte widths
        t = rng.random()
        if t < 0.4:
            cp = rng.randrange(0x00, 0x80)
        elif t < 0.65:
            cp = rng.randrange(0x80, 0x800)
        elif t < 0.9:
            cp = rng.randrange(0x800, 0x10000)
        else:
            cp = rng.randrange(0x10000, 0x110000)
        # avoid surrogates
        if 0xD800 <= cp <= 0xDFFF:
            cp = 0xFFFD
        cps.append(cp)
    return _encode_cps(cps)

# Controlled invalid snippets to exercise exception paths. We inject at most a few bytes
# while keeping the majority valid so both code paths are explored.

def _make_invalid_snippet(rng: random.Random) -> bytes:
    choice = rng.randrange(5)
    if choice == 0:
        # Lone continuation byte
        return bytes([rng.randrange(0x80, 0xC0)])
    if choice == 1:
        # Overlong encoding for '/': should be invalid
        return bytes([0xC0, 0xAF])
    if choice == 2:
        # Start of 3-byte sequence followed by ASCII
        return bytes([0xE1, 0x41, 0x41])
    if choice == 3:
        # 4-byte start then short
        return bytes([0xF0, 0x9F])
    # Surrogate over-encoding (invalid scalar value but often appears)
    return _encode_cps([0xFFFD])  # keep decodable but represents replacement; safe fallback

# Assemble a packet mixing several builders

def _assemble(rng: random.Random, target_size: int) -> bytes:
    parts: List[bytes] = []
    # Start with a valid header to test low-level decode on initial valid segment
    parts.append(_build_boundary_sequence(rng, rng.randint(2, 8)))
    parts.append(_build_ascii_block(rng, rng.randint(10, 60)))
    parts.append(_build_mixed_scripts(rng, rng.randint(10, 40)))

    # Optional long runs to test capacity and counting
    if rng.random() < 0.5:
        parts.append(_build_long_run(rng, 0x00A0, rng.randint(5, 40)))  # non-breaking space
    if rng.random() < 0.5:
        parts.append(_build_long_run(rng, 0x1F600, rng.randint(1, 20)))  # 😀 range

    # Random valid tail
    parts.append(_build_random_valid(rng, rng.randint(20, 120)))

    # Insert a few invalid snippets with low probability to trigger exception path
    invalid_inserts = 0
    if rng.random() < 0.35:
        invalid_inserts = rng.randint(1, 3)
    for _ in range(invalid_inserts):
        insert_at = rng.randrange(len(parts)+1)
        parts.insert(insert_at, _make_invalid_snippet(rng))

    data = b"".join(parts)

    # Optionally trim or pad with additional valid random to approach target_size
    if len(data) > target_size:
        data = data[:target_size]
    else:
        # Pad with valid bytes to stay valid overall
        pad_needed = target_size - len(data)
        if pad_needed > 0:
            tail = _build_random_valid(rng, min(128, pad_needed // 2 + 1))
            data = (data + tail)[:target_size]

    # Occasionally append a NUL to test boundary with embedded zeros (valid UTF-8)
    if rng.random() < 0.2 and len(data) < target_size:
        data += b"\x00"
    return data


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose an overall target size within [0, 1024]; the stub truncates to 1024 anyway.
    # Occasionally produce very small or empty buffers as edge cases.
    if rng.random() < 0.1:
        target = rng.choice([0, 1, 2, 3, 4, 8, 16])
    else:
        target = rng.randint(32, 1024)
    return _assemble(rng, min(4096, target))
